package org.example;
import java.util.List;

public class App {

    public static void main(String[] args) {
        System.out.println(LogParser.parseLine("Jun  1 12:34:56 server sshd[12345]: Failed password for invalid user testuser from 192.168.1.100"));
        LoginAnalyzer analyzer = new LoginAnalyzer(3);
        List<FailedLogin> logins = List.of(new FailedLogin("root", "192.168.1.100"), 
        new FailedLogin("admin", "192.168.1.101"), 
        new FailedLogin("testuser", "192.168.1.100"));
        System.out.println(analyzer.countByIp(List.of(new FailedLogin("testuser", "192.168.1.100"))));
        List<String> flaggedIps = analyzer.flaggedIps(analyzer.countByIp(logins));
        System.out.println(flaggedIps);
    }
}
